-- Marca sincronizada la publicación y procesados sus eventos de precio/stock.
UPDATE channel_listings SET last_synced_at = now(), sync_error = NULL
WHERE variant_id = '{{ $('Traer para ML').item.json.variant_id }}' AND channel = 'mercadolibre';
UPDATE outbox_events SET status = 'processed', processed_at = now()
WHERE aggregate_id = '{{ $('Traer para ML').item.json.variant_id }}'
  AND event_type IN ('price.changed','stock.changed') AND status = 'pending';
